Use Kahn’s algorithm with a min-heap to always select the smallest available vertex. Deduplicate edges before counting indegrees; return [] if not all vertices can be processed.

```javascript
function solve(n, edges) {
  const adjacency = Array.from({ length: n }, () => new Set());
  const indegree = new Array(n).fill(0);

  for (const [u, v] of edges) {
    if (!adjacency[u].has(v)) {
      adjacency[u].add(v);
      indegree[v]++;
    }
  }

  const heap = [];

  function push(value) {
    let i = heap.length;
    heap.push(value);
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent] <= value) break;
      heap[i] = heap[parent];
      i = parent;
    }
    heap[i] = value;
  }

  function pop() {
    const minimum = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return minimum;

    let i = 0;
    while (2 * i + 1 < heap.length) {
      let child = 2 * i + 1;
      if (child + 1 < heap.length &&
          heap[child + 1] < heap[child]) {
        child++;
      }
      if (last <= heap[child]) break;
      heap[i] = heap[child];
      i = child;
    }
    heap[i] = last;
    return minimum;
  }

  for (let vertex = 0; vertex < n; vertex++) {
    if (indegree[vertex] === 0) push(vertex);
  }

  const order = [];
  while (heap.length > 0) {
    const vertex = pop();
    order.push(vertex);
    for (const neighbor of adjacency[vertex]) {
      indegree[neighbor]--;
      if (indegree[neighbor] === 0) push(neighbor);
    }
  }

  return order.length === n ? order : [];
}
```

